import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    pts = [None] * n
    for i in range(n):
        x, y = data[1 + 2*i], data[2 + 2*i]
        pts[x - 1] = y
    adj = [0] * n
    for i in range(n):
        yi = pts[i]
        for j in range(i + 1, n):
            if (yi < pts[j]):
                adj[i] |= 1 << j
            else:
                adj[j] |= 1 << i
    # Reachable remaining sets. Selecting k removes all currently remaining
    # vertices comparable with k; k itself is retained.
    full = (1 << n) - 1
    seen = {full}
    stack = [full]
    while stack:
        mask = stack.pop()
        bits = mask
        while bits:
            b = bits & -bits
            k = b.bit_length() - 1
            bits -= b
            nxt = mask & ~(adj[k] & mask)
            if nxt not in seen:
                seen.add(nxt)
                stack.append(nxt)
    print(len(seen) % 998244353)

if __name__ == '__main__':
    main()

