def main():
 data=list(map(int,sys.stdin.buffer.read().split()))
 if not data:return
 n=data[0]; a=data[1:]
 mx=max(a)
 spf=list(range(mx+1))
 for p in range(2,int(mx**0.5)+1):
  if spf[p]==p:
   for q in range(p*p,mx+1,p):
    if spf[q]==q: spf[q]=p
 phi=list(range(mx+1))
 for p in range(2,mx+1):
  if phi[p]==p:
   for q in range(p,mx+1,p): phi[q]-=phi[q]//p
 bucket=[0]*(mx+1); cache={}
 ans=0; weight=1; out=[]
 for x in a:
  divs=cache.get(x)
  if divs is None:
   factors=[]; y=x
   while y>1:
    p=spf[y]; e=0
    while y%p==0: y//=p; e+=1
    factors.append((p,e))
   divs=[1]
   for p,e in factors:
    old=divs[:]; mul=1
    for _ in range(e):
     mul*=p
     divs.extend(d*mul for d in old)
   cache[x]=divs
  q=0
  for d in divs: q+=phi[d]*bucket[d]
  ans=(2*ans+q)%MOD
  for d in divs:
   v=bucket[d]+weight
   bucket[d]=v-MOD if v>=MOD else v
  out.append(str(ans)); weight=weight*2%MOD
 print('\n'.join(out))
