import sys

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    n = data[0]
    vals = data[1:1+n]
    limit = max(vals, default=1)
    spf = list(range(limit + 1))
    for p in range(2, int(limit ** 0.5) + 1):
        if spf[p] == p:
            for x in range(p * p, limit + 1, p):
                if spf[x] == x:
                    spf[x] = p
    xor = 0
    for a in vals:
        count = 0
        while a > 1:
            a //= spf[a]
            count += 1
        xor ^= count
    print('Anna' if xor else 'Bruno')

if __name__ == '__main__':
    main()

