from typing import List
import heapq

class Solution:
    def maxSubarrays(self, n: int, conflictingPairs: List[List[int]]) -> int:
        by_right = [[] for _ in range(n + 1)]
        for i, (x, y) in enumerate(conflictingPairs):
            a, b = sorted((x, y))
            by_right[b].append((a, i))

        heap = []
        credit = [0] * len(conflictingPairs)
        base = 0

        for r in range(1, n + 1):
            for a, i in by_right[r]:
                heapq.heappush(heap, (-a, i))

            top = -heap[0][0] if heap else 0
            if len(heap) >= 3:
                second = -min(heap[1][0], heap[2][0])
            elif len(heap) == 2:
                second = -heap[1][0]
            else:
                second = 0

            base += r - top
            if heap and top > second:
                credit[heap[0][1]] += top - second

        return base + max(credit)

