class Solution:
    def numberOfWays(self, n: int, x: int, y: int) -> int:
        MOD = 10**9 + 7
        dp = [0] * (x + 1)
        dp[0] = 1
        for i in range(1, n + 1):
            new = [0] * (x + 1)
            for k in range(1, min(i, x) + 1):
                new[k] = (k * dp[k] + (x - k + 1) * y * dp[k - 1]) % MOD
            dp = new
        return sum(dp) % MOD

