class Solution:
    def countKReducibleNumbers(self, s: str, k: int) -> int:
        MOD = 10**9 + 7
        n = len(s)
        comb = [[0] * (n + 1) for _ in range(n + 1)]
        comb[0][0] = 1
        for a in range(1, n + 1):
            comb[a][0] = comb[a][a] = 1
            for b in range(1, a):
                comb[a][b] = (comb[a - 1][b - 1] + comb[a - 1][b]) % MOD
        good = [False] * (n + 1)
        for j in range(1, n + 1):
            t = j
            steps = 0
            while t > 1:
                t = t.bit_count()
                steps += 1
            good[j] = steps <= k - 1
        ans = 0
        prefix_ones = 0
        for i, ch in enumerate(s):
            if ch == '1':
                rem = n - i - 1
                for r in range(rem + 1):
                    total = prefix_ones + r
                    if total > 0 and good[total]:
                        ans += comb[rem][r]
                prefix_ones += 1
        return ans % MOD

