import sys
from collections import deque

def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    if not data:
        return
    it = iter(data)
    n, m, q = next(it), next(it), next(it)
    people = []
    for _ in range(m):
        s, t = next(it), next(it)
        l, r = min(s, t), max(s, t)
        people.append((l, r, s < t))
    queries = [(next(it), next(it)) for _ in range(q)]
    out = []
    for left, right in queries:
        graph = [[] for _ in range(n + 1)]
        for i in range(left - 1, right):
            l, r, forward = people[i]
            graph[l].append((r, 0))
            graph[r].append((l, 0))
            if forward:
                for x in range(l + 1, r):
                    graph[l].append((x, 1))
            else:
                for x in range(l + 1, r):
                    graph[x].append((r, 1))
        dist = [0] * (n + 1)
        count = [0] * (n + 1)
        inq = [True] * (n + 1)
        dq = deque(range(1, n + 1))
        ok = True
        while dq and ok:
            u = dq.popleft()
            inq[u] = False
            for v, w in graph[u]:
                nd = dist[u] + w
                if nd > dist[v]:
                    dist[v] = nd
                    count[v] += 1
                    if count[v] >= n:
                        ok = False
                        break
                    if not inq[v]:
                        inq[v] = True
                        dq.append(v)
        out.append('Yes' if ok else 'No')
    sys.stdout.write('\n'.join(out))

if __name__ == '__main__':
    main()

