import sys
from collections import deque

def main():
    data=sys.stdin.read().split()
    if not data: return
    n=int(data[0]); rows=data[1:]
    incoming=[{} for _ in range(n)]
    outgoing=[{} for _ in range(n)]
    for x in range(n):
        for y,ch in enumerate(rows[x]):
            if ch!='-':
                incoming[y].setdefault(ch,[]).append(x)
                outgoing[x][ch]=outgoing[x].get(ch,0)|(1<<y)
    dist=[[-1]*n for _ in range(n)]
    seen=[0]*n
    q=deque()
    for i in range(n):
        dist[i][i]=0; seen[i]|=1<<i; q.append((i,i))
    for i in range(n):
        for j,ch in enumerate(rows[i]):
            if ch!='-' and dist[i][j]<0:
                dist[i][j]=1; seen[i]|=1<<j; q.append((i,j))
    while q:
        u,v=q.popleft(); nd=dist[u][v]+2
        for ch, xs in incoming[u].items():
            mask=outgoing[v].get(ch,0)
            if not mask: continue
            for x in xs:
                new=mask & ~seen[x]
                if new:
                    seen[x]|=new
                    drow=dist[x]
                    while new:
                        bit=new&-new; y=bit.bit_length()-1
                        drow[y]=nd; q.append((x,y)); new-=bit
    print('\n'.join(' '.join(map(str,r)) for r in dist))
main()

