import sys

def solve():
    data=list(map(int,sys.stdin.buffer.read().split()))
    if not data: return
    n,m=data[:2]
    rows=[0]*n; k=2
    for _ in range(m):
        u,v=data[k]-1,data[k+1]-1; k+=2
        rows[u]|=1<<v; rows[v]|=1<<u
    pivots=[]; r=0
    for c in range(n):
        p=next((i for i in range(r,n) if (rows[i]>>c)&1),None)
        if p is None: continue
        rows[r],rows[p]=rows[p],rows[r]
        for i in range(r+1,n):
            if (rows[i]>>c)&1: rows[i]^=rows[r]
        pivots.append(c); r+=1
