from typing import List
from math import factorial

class Solution:
    def permute(self, n: int, k: int) -> List[int]:
        odds = (n + 1) // 2
        evens = n // 2
        fact = [factorial(i) for i in range(n + 1)]
        remaining = set(range(1, n + 1))
        result = []
        prev_parity = None

        def completions(rem_odd: int, rem_even: int, slots: int, next_parity: int) -> int:
            need_odd = 0
            need_even = 0
            p = next_parity
            for _ in range(slots):
                if p:
                    need_odd += 1
                else:
                    need_even += 1
                p ^= 1
            if need_odd != rem_odd or need_even != rem_even:
                return 0
            return fact[rem_odd] * fact[rem_even]

        while remaining:
            for x in sorted(remaining):
                parity = x % 2
                if prev_parity is not None and parity == prev_parity:
                    continue
                ro = sum(1 for y in remaining if y % 2 == 1) - (parity == 1)
                re = len(remaining) - 1 - ro
                count = completions(ro, re, len(remaining) - 1, 1 - parity)
                if k > count:
                    k -= count
                else:
                    result.append(x)
                    remaining.remove(x)
                    prev_parity = parity
                    break
            else:
                return []
        return result

