class Solution:
    def largestPalindrome(self, n: int, k: int) -> str:
        m = (n + 1) // 2
        p = [1 % k] * n
        for i in range(1, n):
            p[i] = p[i - 1] * 10 % k
        coeff = []
        for i in range(m):
            if n % 2 and i == m - 1:
                coeff.append(p[i])
            else:
                coeff.append((p[i] + p[n - 1 - i]) % k)
        full = (1 << k) - 1
        reach = [0] * (m + 1)
        reach[m] = 1
        for i in range(m - 1, -1, -1):
            mask = reach[i + 1]
            c = coeff[i]
            out = 0
            for d in range(10):
                sh = (d * c) % k
                if sh == 0:
                    out |= mask
                else:
                    out |= ((mask << sh) | (mask >> (k - sh))) & full
            reach[i] = out
        digits = []
        rem = 0
        for i, c in enumerate(coeff):
            low = 1 if i == 0 else 0
            for d in range(9, low - 1, -1):
                need = (-(rem + d * c)) % k
                if (reach[i + 1] >> need) & 1:
                    digits.append(str(d))
                    rem = (rem + d * c) % k
                    break
        half = ''.join(digits)
        if n % 2:
            return half + half[:-1][::-1]
        return half + half[::-1]

