from bisect import bisect_left

class Solution:
    def shortestMatchingSubstring(self, s: str, p: str) -> int:
        parts = p.split('*')
        n = len(s)

        def occurrences(t):
            if not t:
                return []
            m = len(t)
            pi = [0] * m
            j = 0
            for i in range(1, m):
                while j and t[i] != t[j]:
                    j = pi[j - 1]
                if t[i] == t[j]:
                    j += 1
                pi[i] = j
            out = []
            j = 0
            for i, ch in enumerate(s):
                while j and ch != t[j]:
                    j = pi[j - 1]
                if ch == t[j]:
                    j += 1
                if j == m:
                    out.append(i - m + 1)
                    j = pi[j - 1]
            return out

        nonempty = [(i, x, occurrences(x)) for i, x in enumerate(parts) if x]
        if not nonempty:
            return 0
        if any(not occ for _, _, occ in nonempty):
            return -1
        first_occ = nonempty[0][2]
        best = n + 1
        for start in first_occ:
            end = start + len(nonempty[0][1])
            for _, frag, occ in nonempty[1:]:
                k = bisect_left(occ, end)
                if k == len(occ):
                    break
                end = occ[k] + len(frag)
            else:
                best = min(best, end - start)
        return -1 if best == n + 1 else best

