from typing import List

class Solution:
    def findAnswer(self, parent: List[int], s: str) -> List[bool]:
        n = len(parent)
        children = [[] for _ in range(n)]
        for v in range(1, n):
            children[parent[v]].append(v)

        # Produce the postorder traversal without recursion.
        order = []
        stack = [0]
        while stack:
            x = stack.pop()
            if x < 0:
                order.append(~x)
            else:
                stack.append(~x)
                for y in reversed(children[x]):
                    stack.append(y)

        pos = [0] * n
        for i, x in enumerate(order):
            pos[x] = i

        # A subtree occupies a contiguous interval in postorder.
        size = [1] * n
        for x in order:
            if parent[x] >= 0:
                size[parent[x]] += size[x]

        text = ''.join(s[x] for x in order)

        # Manacher radii: odd[i] counts palindromes centered on i,
        # even[i] counts palindromes centered immediately before i.
        odd = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 1 if i > right else min(odd[left + right - i], right - i + 1)
            while i - k >= 0 and i + k < n and text[i - k] == text[i + k]:
                k += 1
            odd[i] = k
            if i + k - 1 > right:
                left, right = i - k + 1, i + k - 1

        even = [0] * n
        left, right = 0, -1
        for i in range(n):
            k = 0 if i > right else min(even[left + right - i + 1], right - i + 1)
            while i - k - 1 >= 0 and i + k < n and text[i - k - 1] == text[i + k]:
                k += 1
            even[i] = k
            if i + k - 1 > right:
                left, right = i - k, i + k - 1

        answer = []
        for x in range(n):
            length = size[x]
            start = pos[x] - length + 1
            if length % 2:
                center = (start + pos[x]) // 2
                answer.append(odd[center] >= length // 2 + 1)
            else:
                center = (start + pos[x] + 1) // 2
                answer.append(even[center] >= length // 2)
        return answer

