class Solution:
    def maxSubarraySum(self, nums: List[int], k: int) -> int:
        min_prefix = {0: 0}
        prefix = 0
        best = None
        for j, x in enumerate(nums, 1):
            prefix += x
            r = j % k
            if r in min_prefix:
                cand = prefix - min_prefix[r]
                if best is None or cand > best:
                    best = cand
            if r not in min_prefix or prefix < min_prefix[r]:
                min_prefix[r] = prefix
        return best

