class Solution:
    def lengthAfterTransformations(self, s: str, t: int) -> int:
        mod = 10**9 + 7
        lengths = [1] * 26
        for _ in range(t):
            nxt = [0] * 26
            for i in range(25):
                nxt[i] = lengths[i + 1]
            nxt[25] = (lengths[0] + lengths[1]) % mod
            lengths = nxt
        return sum(lengths[ord(ch) - 97] for ch in s) % mod

