import heapq
class Solution:
    def minOperations(self, n: int, m: int) -> int:
        def prime(x):
            if x < 2: return False
            if x % 2 == 0: return x == 2
            d = 3
            while d*d <= x:
                if x % d == 0: return False
                d += 2
            return True
        if prime(n) or prime(m):
            return -1
        length = len(str(n))
        low = 0 if length == 1 else 10**(length-1)
        high = 10**length - 1
        dist = {n: n}
        heap = [(n, n)]
        while heap:
            cost, x = heapq.heappop(heap)
            if dist.get(x) != cost: continue
            if x == m: return cost
            p = 1
            while p <= high:
                digit = (x // p) % 10
                for delta in (-1, 1):
                    nd = digit + delta
                    if 0 <= nd <= 9:
                        y = x + delta*p
                        if low <= y <= high and not prime(y):
                            nc = cost + y
                            if nc < dist.get(y, 10**30):
                                dist[y] = nc
                                heapq.heappush(heap, (nc, y))
                p *= 10
        return -1

