from typing import List

class Solution:
    def beautifulSplits(self, nums: List[int]) -> int:
        n = len(nums)
        if n < 3:
            return 0
        z = [0] * n
        l = r = 0
        for i in range(1, n):
            if i < r:
                z[i] = min(r - i, z[i - l])
            while i + z[i] < n and nums[z[i]] == nums[i + z[i]]:
                z[i] += 1
            if i + z[i] > r:
                l, r = i, i + z[i]
        ans = 0
        nxt = [0] * (n + 1)
        for i in range(n - 2, 0, -1):
            cur = [0] * (n + 1)
            for j in range(n - 1, i, -1):
                if nums[i] == nums[j]:
                    cur[j] = nxt[j + 1] + 1
                if z[i] >= i or cur[j] >= j - i:
                    ans += 1
            nxt = cur
        return ans

