from typing import List
class Solution:
    def maxRemovals(self, source: str, pattern: str, targetIndices: List[int]) -> int:
        m = len(pattern)
        neg = -10**9
        dp = [neg] * (m + 1)
        dp[0] = 0
        targets = set(targetIndices)
        for i, ch in enumerate(source):
            ndp = dp.copy()
            if i in targets:
                for j, v in enumerate(dp):
                    if v != neg and v + 1 > ndp[j]:
                        ndp[j] = v + 1
            for j in range(m):
                if ch == pattern[j] and dp[j] > ndp[j + 1]:
                    ndp[j + 1] = dp[j]
            dp = ndp
        return dp[m]

if __name__ == '__main__':
