from typing import List
class Solution:
    def minCost(self, n: int, cost: List[List[int]]) -> int:
        # State is the colors on the outer pair: (left, right).
        INF = 10**30
        dp = [[INF] * 3 for _ in range(3)]
        for a in range(3):
            for b in range(3):
                if a != b:
                    dp[a][b] = cost[0][a] + cost[n - 1][b]

        for i in range(1, n // 2):
            ndp = [[INF] * 3 for _ in range(3)]
            left, right = i, n - 1 - i
            for a in range(3):
                for b in range(3):
                    if dp[a][b] == INF:
                        continue
                    for c in range(3):
                        if c == a:
                            continue
                        for d in range(3):
                            if d == b or d == c:
                                continue
                            val = dp[a][b] + cost[left][c] + cost[right][d]
                            if val < ndp[c][d]:
                                ndp[c][d] = val
            dp = ndp
        return min(min(row) for row in dp)

