# Check candidate formula versus direct operation enumeration on all short binary strings.
from itertools import product

def formula(s):
 t='1'+s+'1'; runs=[]; i=0
 while i<len(t):
  j=i+1
  while j<len(t) and t[j]==t[i]: j+=1
  runs.append((t[i],j-i)); i=j
 ones=s.count('1'); ans=ones
 for k,(c,l) in enumerate(runs):
  if c=='1' and 0<k<len(runs)-1: ans=max(ans,ones+runs[k-1][1]+runs[k+1][1])
 return ans

def brute(s):
 t='1'+s+'1'; best=s.count('1')
 n=len(s)
 for a in range(1,len(t)-1):
  for b in range(a,len(t)-1):
   if t[a:b+1].count('0')==0 and t[a-1]=='0' and t[b+1]=='0':
    u=t[:a]+'0'*(b-a+1)+t[b+1:]
    for c in range(1,len(t)-1):
     for d in range(c,len(t)-1):
      if u[c:d+1].count('0')==d-c+1 and u[c-1]=='1' and u[d+1]=='1':
       v=u[:c]+'1'*(d-c+1)+u[d+1:]
       best=max(best,v[1:-1].count('1'))
 return best
for n in range(1,9):
 for x in product('01',repeat=n):
  s=''.join(x)
  if formula(s)!=brute(s): print('bad',s,formula(s),brute(s)); raise SystemExit
print('all short strings agree')

