class Solution:
    def calculateScore(self, s: str) -> int:
        stacks = [[] for _ in range(26)]
        score = 0
        for i, ch in enumerate(s):
            x = ord(ch) - 97
            other = 25 - x
            if stacks[other]:
                j = stacks[other].pop()
                score += i - j
            else:
                stacks[x].append(i)
        return score

